INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-03' FROM countries WHERE name_en = 'Jordan';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Centralized clearance — JoFotara (National Electronic Invoicing System)', 'This deep-dive page reflects publicly available ISTD guidance and industry reporting as of August 2026 and is provided for general awareness, not legal or tax advice. Penalty enforcement practice and onboarding details continue to evolve — confirm current requirements directly with the Income and Sales Tax Department or your integration provider before building against them.', 'Jordan''s JoFotara rollout has run in clear stages since its December 2022 voluntary launch: mandatory onboarding for large taxpayers from January 2023, universal registration for all VAT-registered taxpayers by May 2024, and full legal enforcement across B2B, B2G, and B2C transactions from 1 April 2025 — with a penalty grace period for late registrants closing at the end of May 2025.', 'JoFotara invoices are authored in XML and converted to encrypted JSON for transmission to the platform, following a UBL 2.1-based structure. There is no separate legacy Jordanian schema to learn beyond this.', 'JoFotara is a centralized clearance Continuous Transaction Control (CTC) model: every invoice must be submitted to and validated by the platform, in real or near-real time, before it has legal or tax effect — this applies uniformly across B2B, B2G, and B2C, plus cross-border transactions for resident taxpayers, with no SME or small-business exemption.', 'Getting compliant means registering with the ISTD, choosing an integration route, mapping your invoice content to JoFotara''s required fields, and testing before your applicable deadline — the free web portal exists precisely so small taxpayers without in-house systems aren''t excluded.', 'Jordan backs its mandate with real, escalating penalties: fixed fines per violation, imprisonment for persistent non-compliance, and — the mandate''s real enforcement engine — outright invalidity of non-compliant invoices for VAT input deduction.', 'Jordan''s JoFotara e-invoicing system has been mandatory for large taxpayers since January 2023, extended to universal VAT-registered coverage by May 2024, and reached full legal enforcement across B2B, B2G, and B2C transactions on 1 April 2025 — invoices not transmitted through JoFotara are invalid for VAT deduction, and fines of JOD 500 or more apply.', '🇯🇴' FROM countries WHERE name_en = 'Jordan';
