INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Jordan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & standard', '[["Authoring format", "XML, UBL 2.1-based structure"], ["Transmission format", "Converted to encrypted JSON for the JoFotara API"], ["Validation artifact", "ISTD-issued QR code plus a unique reference embedded on the cleared invoice"], ["Legal basis", "Billing and Control Regulation, supervised by the Income and Sales Tax Department"]]', 'The XML-authored, JSON-transmitted pattern means most modern invoicing systems already produce a workable starting format — the real integration work is the API connection and content mapping, not inventing a new file type.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Jordan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Identifiers & registration', '[["Taxpayer identity", "Jordanian tax registration number"], ["Access routes", "Direct API, the free JoFotara web portal, or a certified third-party service provider"], ["Registration portal", "portal.jofotara.gov.jo"], ["Reporting dashboard", "dashboard.jofotara.gov.jo"]]', 'The free web portal specifically exists so the mandate''s no-SME-exemption policy doesn''t strand small taxpayers without accounting software — a real consideration given Jordan applies this to individual professionals too.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Jordan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory content & archiving', '[["Party data", "Seller and buyer tax registration numbers"], ["Invoice types", "Cash, receivable, income, sales, special sales, simplified, and credit invoices"], ["Simplified invoice threshold", "Customer details optional below roughly JOD 10,000"], ["Retention period", "4 years, per Regulation No. 34 of 2019"]]', 'The simplified-invoice threshold is a convenience for low-value B2C sales, not an exemption — any invoice to a VAT-registered buyer still needs full standard-invoice content regardless of value.', NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 0, 'pills' FROM countries WHERE name_en = 'Jordan';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The clearance flow', 'Every JoFotara invoice moves through the same real-time sequence:', 'Nothing reaches the customer until the ISTD has cleared it — this is what makes JoFotara a genuine clearance model rather than a post-transaction reporting system.');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 0, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Invoice drafted');
