INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Jordan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Who''s in scope, and since when', '[["Large taxpayers", "Mandatory since January 2023 (Phase 1)"], ["All VAT-registered taxpayers", "Mandatory registration since May 2024, full enforcement since April 2025"], ["Individual professionals", "Included — no exemption for consultants, doctors, lawyers, etc."], ["Cross-border trade", "Included for resident taxpayers"]]', 'There is genuinely no small-business carve-out here — Jordan applies JoFotara to the smallest registered taxpayer the same way it applies to the largest, just with a longer runway to comply.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Jordan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Integration channels', '[["Direct API", "Credentials issued by the ISTD for system-to-system integration"], ["Web portal", "Free, for businesses without existing invoicing systems"], ["Third-party providers", "Certified service providers offering managed integration"]]', 'The three-route design mirrors Egypt''s and Oman''s approach in this tracker: high-volume businesses integrate directly, while the free portal keeps low-volume and small taxpayers from being priced out of compliance.', NULL);
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Jordan';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Initial non-compliance', 'Approximately JOD 500 per violation', NULL);
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Jordan';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Persistent non-compliance', 'Fines up to JOD 1,000, or imprisonment of 3-6 months, or both', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Jordan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🧾 VAT consequences — the real enforcement engine', NULL, NULL, 'An invoice not transmitted through JoFotara is invalid for VAT input deduction and accounting purposes. A non-compliant supplier doesn''t just risk a fine — their invoices become worthless to their VAT-registered business customers, which drives compliance far more effectively than the fines alone.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Jordan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🏛️ Government contract exclusion', NULL, NULL, 'Non-compliant businesses lose eligibility for public-sector tenders and contracts — a meaningful commercial consequence beyond the direct financial penalty for any business that sells or wants to sell to Jordan''s government.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Jordan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⏰ The grace period has already closed', NULL, NULL, 'A waiver on accrued fines was available for businesses that registered before 31 May 2025 — that grace period is now closed, so late registrants face the full penalty structure without any waiver protection.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Jordan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your registration status with the ISTD', 'Every VAT-registered business and individual professional is in scope with no exemption — confirm directly with the Income and Sales Tax Department rather than assuming your size or sector puts you outside it.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Jordan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Register with JoFotara if you haven''t already', 'The penalty-waiver grace period closed 31 May 2025, so registering now means facing the full fine structure for any past non-compliance — do it promptly rather than risk compounding the exposure.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Jordan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Choose your integration route', 'High-volume businesses should integrate via direct API; the free web portal suits low-volume and small taxpayers, and certified third-party providers offer a managed middle ground.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Jordan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Map your invoice content to JoFotara''s required fields', 'Cover every invoice type you issue — cash, receivable, income, sales, special sales, simplified, and credit — since each carries its own mandatory-field expectations.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Jordan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Route every sales channel through JoFotara', 'Confirm POS, e-commerce, and manual invoicing all clear through the platform before relying on any of them — an invoice outside JoFotara has no legal effect regardless of the channel it came from.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Jordan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Audit your customers'' invoices before relying on them for VAT deduction', 'Check for a valid ISTD-issued QR code and reference before treating a supplier''s invoice as deductible — the compliance burden runs in both directions.');
